renderer.valueExpression:
var permit = $feature.PERMIT_TYPE;

var PhaseI = "Stormwater - Municipal Separate Storm Sewer Systems";

var PhaseII = [
  "MS2, >50K",
  "MS2, > 10-50K",
  "MSE, < OR = 10K or Other"
];

if (permit == PhaseI) {
  return "Phase I MS4";
} else if (Includes(PhaseII, permit)) {
  return "Phase II MS4";
}

return "Other / Unclassified";

var permit = $feature.PERMIT_TYPE;
var fac = $feature.FACILITY_TYPE_CODE;

// Define permit size groupings
var largePermits = [
  "Stormwater - Large Construction (>= 5 AC)",
  "Construction Generic Dewatering Large"
];

var smallPermits = [
  "Stormwater - Small Construction (1-5 AC)",
  "Construction Generic Dewatering Small"
];

var isLarge = Includes(largePermits, permit);
var isSmall = Includes(smallPermits, permit);

// CGD Combinations
if (fac == "CGD") {
  if (isLarge) return "CGD (>= 5 Acres)";
  if (isSmall) return "CGD (<= 5 Acres)";
}

// CGP Combinations (including the specific MSP + Large Construction rule)
if (fac == "CGP") {
  if (isLarge) return "CGP (>= 5 Acres)";
  if (isSmall) return "CGP (<= 5 Acres)";
} else if (fac == "MSP" && permit == "Stormwater - Large Construction (>= 5 AC)") {
  return "CGP (>= 5 Acres)";
}

// Fallback for features that don't match any of these criteria
return "Other / Unclassified";
